import { test, expect } from '@playwright/test';

test.describe('401 Error Handling - Redirect to Login', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the app
    await page.goto('/');
  });

  test('should redirect to login when receiving 401 error from API', async ({ page }) => {
    // Mock an API endpoint to return 401 Unauthorized
    await page.route('**/api/protected/**', route => {
      route.abort('failed');
    });

    // Alternatively, mock with 401 response
    await page.route('**/api/user/profile', route => {
      route.respond({
        status: 401,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Unauthorized' })
      });
    });

    // Attempt to access a protected resource
    await page.goto('/dashboard');

    // Wait for redirect to login page
    await page.waitForURL('**/login');

    // Verify we are on the login page
    const loginHeading = page.getByRole('heading', { name: /login/i });
    await expect(loginHeading).toBeVisible();

    // Verify login form is present
    const emailInput = page.getByLabel(/email/i);
    const passwordInput = page.getByLabel(/password/i);
    await expect(emailInput).toBeVisible();
    await expect(passwordInput).toBeVisible();
  });

  test('should display error message when 401 response received during authenticated request', async ({ page }) => {
    // Set up authentication token
    await page.context().addCookies([
      {
        name: 'authToken',
        value: 'expired_token',
        url: 'http://localhost'
      }
    ]);

    // Mock API to return 401 when accessing protected endpoint
    await page.route('**/api/protected/data', route => {
      route.respond({
        status: 401,
        contentType: 'application/json',
        body: JSON.stringify({ 
          error: 'Token expired',
          message: 'Your session has expired. Please login again.'
        })
      });
    });

    // Navigate to page that makes the protected API call
    await page.goto('/protected-page');

    // Wait for redirect to login
    await page.waitForURL('**/login', { timeout: 5000 });

    // Verify login page is displayed
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Verify we can see login form elements
    const emailField = page.getByLabel(/email address/i);
    await expect(emailField).toBeVisible();
  });

  test('should clear user session data before redirecting to login on 401', async ({ page }) => {
    // Set up initial authenticated state
    await page.context().addCookies([
      {
        name: 'authToken',
        value: 'valid_token',
        url: 'http://localhost'
      }
    ]);

    // Mock API to return 401
    await page.route('**/api/user/**', route => {
      route.respond({
        status: 401,
        contentType: 'application/json',
        body: JSON.stringify({ error: 'Unauthorized' })
      });
    });

    // Navigate to authenticated page
    await page.goto('/profile');

    // Wait for redirect
    await page.waitForURL('**/login');

    // Verify auth token is cleared from cookies
    const cookies = await page.context().cookies();
    const authCookie = cookies.find(c => c.name === 'authToken');
    expect(authCookie).toBeUndefined();

    // Verify login page is shown
    const loginForm = page.getByRole('form', { name: /login/i });
    await expect(loginForm).toBeVisible();
  });
});
